    "explanation": "**[핵심 개념]**\n이 문제는 이차함수의 계수를 구하는 문제이다. 주어진 조건들을 이용하여:\n- 함수값 조건: $f(0) = 3$\n- 정적분 조건: $\\int_0^2 f(x)dx = 10$\n- 도함수 조건: $f'(1) = 4$\n\n이 세 조건으로부터 미지수 $a, b, c$를 결정한 후, 구하는 적분값을 계산한다.\n\n**[풀이]**\n\n**1단계: 조건 (가)에서 $c$ 구하기**\n\n$f(x) = ax^2 + bx + c$이므로\n$$f(0) = c = 3$$\n\n따라서 $c = 3$\n\n**2단계: 조건 (나)에서 $a, b$의 관계식 구하기**\n\n$$\\int_0^2 f(x)dx = \\int_0^2 (ax^2 + bx + 3)dx$$\n\n$$= \\left[\\frac{ax^3}{3} + \\frac{bx^2}{2} + 3x\\right]_0^2$$\n\n$$= \\frac{8a}{3} + 2b + 6 = 10$$\n\n$$\\frac{8a}{3} + 2b = 4$$\n\n양변에 3을 곱하면:\n$$8a + 6b = 12$$\n$$4a + 3b = 6 \\quad \\cdots (1)$$\n\n**3단계: 조건 (다)에서 또 다른 관계식 구하기**\n\n$$f'(x) = 2ax + b$$\n$$f'(1) = 2a + b = 4 \\quad \\cdots (2)$$\n\n**4단계: 연립방정식 풀기**\n\n식 (2)에서: $b = 4 - 2a$\n\n이를 식 (1)에 대입:\n$$4a + 3(4 - 2a) = 6$$\n$$4a + 12 - 6a = 6$$\n$$-2a = -6$$\n$$a = 3$$\n\n따라서 $b = 4 - 2(3) = -2$\n\n**5단계: $\\int_1^3 f(x)dx$ 계산**\n\n$f(x) = 3x^2 - 2x + 3$이므로\n\n$$\\int_1^3 f(x)dx = \\int_1^3 (3x^2 - 2x + 3)dx$$\n\n$$= \\left[x^3 - x^2 + 3x\\right]_1^3$$\n\n$$= (27 - 9 + 9) - (1 - 1 + 3)$$\n\n$$= 27 - 3 = 24$$\n\n**[정답 확인]**\n세 조건을 모두 만족하는 $f(x) = 3x^2 - 2x + 3$에 대해 정적분을 계산하면 24가 나온다.\n\n**[오답 분석]**\n- ① 18: 적분 계산 실수 (상한과 하한 계산 오류)\n- ② 20: $3x$항의 계수를 잘못 적분한 경우\n- ③ 22: 부정적분 후 대입 시 부호 실수\n- ⑤ 26: 조건 (나)를 풀 때 계산 오류로 잘못된 $a, b$ 값을 구한 경우\n\n**[핵심 포인트]**\n1. 주어진 조건들을 체계적으로 정리하여 미지수 개수만큼 독립적인 방정식을 세우는 것이 중요하다.\n2. 정적분 계산할 때 상한과 하한을 정확히 대입하고, 부호 실수를 피해야 한다.",
