    "explanation": "**[핵심 개념]**\n부정적분은 미분의 역연산이다. 다항함수의 부정적분은 다음 공식을 사용한다:\n$$\\int x^n \\, dx = \\frac{x^{n+1}}{n+1} + C \\quad (n \\neq -1)$$\n여기서 $C$는 적분상수이다. 또한 상수배는 적분 기호 밖으로 꺼낼 수 있다:\n$$\\int k \\cdot f(x) \\, dx = k \\int f(x) \\, dx$$\n\n**[풀이]**\n$$\\int 3x^2 \\, dx$$\n\n**1단계: 상수 꺼내기**\n$$= 3 \\int x^2 \\, dx$$\n\n**2단계: 멱의 법칙(power rule) 적용**\n$\\int x^n \\, dx = \\frac{x^{n+1}}{n+1} + C$를 사용하여 $n=2$를 대입하면:\n$$= 3 \\cdot \\frac{x^{2+1}}{2+1} + C$$\n\n**3단계: 정리**\n$$= 3 \\cdot \\frac{x^3}{3} + C$$\n\n$$= x^3 + C$$\n\n**[정답 확인]**\n$\\frac{d}{dx}(x^3 + C) = 3x^2$이므로, 구한 답을 미분하면 원래 피적분함수가 나온다.\n\n**[오답 분석]**\n- **②번 $3x^3 + C$**: 상수 3을 곱한 후 거듭제곱 공식을 적용하지 않았다. 미분하면 $9x^2$가 나온다.\n- **③번 $x^3 + 3x + C$**: $3x$ 항이 불필요하다. 정적분이 아닌 부정적분이므로 이런 형태가 나올 수 없다.\n- **④번 $6x + C$**: 미분의 거듭제곱 법칙을 역으로 적용하지 않았다. 이는 $6$을 미분한 것처럼 보이다.\n- **⑤번 $9x^2 + C$**: 주어진 식을 미분한 것이다. 적분과 미분을 혼동한 경우이다.\n\n**[핵심 포인트]**\n부정적분은 **거듭제곱을 1 증가시키고 새로운 거듭제곱으로 나누는** 멱의 법칙을 사용한다. 항상 미분으로 검산하여 $\\frac{d}{dx}$(답) = 피적분함수인지 확인한다.",
