    "explanation": "**[핵심 개념]**\n부분적분(Integration by Parts)을 이용하여 $\\int u \\, dv = uv - \\int v \\, du$ 형태로 계산한다.\n$f(x) = xe^{2x}$는 다항함수와 지수함수의 곱이므로 부분적분이 필수적이다.\n지수함수의 적분: $\\int e^{2x}dx = \\frac{1}{2}e^{2x} + C$\n\n**[풀이]**\n\n$\\int xe^{2x}dx$를 부분적분으로 계산한다.\n\n$u = x$, $dv = e^{2x}dx$로 설정하면:\n- $du = dx$\n- $v = \\int e^{2x}dx = \\frac{1}{2}e^{2x}$\n\n부분적분 공식 $\\int u \\, dv = uv - \\int v \\, du$를 적용하면:\n\n$$\\int xe^{2x}dx = x \\cdot \\frac{1}{2}e^{2x} - \\int \\frac{1}{2}e^{2x}dx$$\n\n$$= \\frac{1}{2}xe^{2x} - \\frac{1}{2}\\int e^{2x}dx$$\n\n$$= \\frac{1}{2}xe^{2x} - \\frac{1}{2} \\cdot \\frac{1}{2}e^{2x} + C$$\n\n$$= \\frac{1}{2}xe^{2x} - \\frac{1}{4}e^{2x} + C$$\n\n**[정답 확인]**\n미분으로 검증: $\\frac{d}{dx}\\left(\\frac{1}{2}xe^{2x} - \\frac{1}{4}e^{2x}\\right) = \\frac{1}{2}e^{2x} + \\frac{1}{2}x \\cdot 2e^{2x} - \\frac{1}{4} \\cdot 2e^{2x} = \\frac{1}{2}e^{2x} + xe^{2x} - \\frac{1}{2}e^{2x} = xe^{2x}$ ✓\n\n**[오답 분석]**\n- ② 부호 오류: $-\\frac{1}{4}$를 $+\\frac{1}{4}$로 잘못 계산\n- ③ 부분적분을 하지 않고 각각 적분: $u = x$일 때 $v = e^{2x}$로 잘못 계산\n- ④ $\\frac{1}{2}$를 $\\frac{1}{4}$로 잘못 계산하고 부호도 틀림\n- ⑤ 계수를 완전히 잘못 계산\n\n**[핵심 포인트]**\n부분적분에서 **다항함수를 $u$로, 지수함수를 $dv$로 설정**하는 것이 중요하다.\n**미분으로 검증하는 습관**이 계산 실수를 방지한다.",
