    "explanation": "**[핵심 개념]**\n\n이 문제는 주어진 도함수로부터 원함수를 구하는 **부정적분** 문제이다. 핵심은 $f'(x) = 2x\\sin x + x^2\\cos x$를 보고 어떤 함수를 미분했을 때 이 형태가 나오는지 역으로 추적하는 것이다. **곱의 미분법** $(uv)' = u'v + uv'$의 역방향 적용이 필요하다.\n\n**[풀이]**\n\n**Step 1: 도함수의 형태 분석**\n\n$f'(x) = 2x\\sin x + x^2\\cos x$를 관찰하면:\n$$f'(x) = 2x\\sin x + x^2\\cos x$$\n\n이를 다시 쓰면:\n$$f'(x) = (x^2)' \\sin x + x^2(\\sin x)'$$\n\n**Step 2: 곱의 미분법 역적용**\n\n곱의 미분법에 의해:\n$$(x^2 \\sin x)' = (x^2)'\\sin x + x^2(\\sin x)'$$\n$$= 2x\\sin x + x^2\\cos x$$\n\n따라서:\n$$f'(x) = (x^2\\sin x)'$$\n\n**Step 3: 원함수 구하기**\n\n양변을 적분하면:\n$$f(x) = x^2\\sin x + C$$\n\n초기조건 $f(0) = 1$을 이용하여 적분상수 $C$를 구한다:\n$$f(0) = 0^2 \\cdot \\sin 0 + C = 0 + C = 1$$\n$$\\therefore C = 1$$\n\n따라서:\n$$f(x) = x^2\\sin x + 1$$\n\n**Step 4: $f(\\frac{\\pi}{2})$ 계산**\n\n$$f\\left(\\frac{\\pi}{2}\\right) = \\left(\\frac{\\pi}{2}\\right)^2 \\sin\\frac{\\pi}{2} + 1$$\n$$= \\frac{\\pi^2}{4} \\cdot 1 + 1$$\n$$= \\frac{\\pi^2}{4} + 1$$\n\n**[정답 확인]**\n\n$f(x) = x^2\\sin x + 1$을 미분하면 $f'(x) = 2x\\sin x + x^2\\cos x$가 되고, $f(0) = 1$을 만족하므로 올바른 원함수이다. 따라서 $f(\\frac{\\pi}{2}) = \\frac{\\pi^2}{4} + 1$이 정답이다.\n\n**[오답 분석]**\n\n- **② $\\frac{\\pi^2}{4}$**: 초기조건의 상수항 $+1$을 빠뜨린 경우\n- **③ $\\pi^2 + 1$**: $(\\frac{\\pi}{2})^2 = \\frac{\\pi^2}{4}$를 $\\pi^2$로 잘못 계산\n- **④ $\\pi^2$**: ②와 ③의 오류를 동시에 범한 경우\n- **⑤ $\\frac{\\pi^2}{2} + 1$**: $\\sin\\frac{\\pi}{2} = 1$을 올바르게 적용했으나 $(\\frac{\\pi}{2})^2 = \\frac{\\pi^2}{2}$로 잘못 계산\n\n**[핵심 포인트]**\n\n1. **곱의 미분법의 역적용**: $f'(x) = u'v + uv'$ 형태를 보면 $(uv)'$임을 인식하는 것이 핵심\n2. **초기조건 활용**: 부정적분에서 나온 적분상수는 반드시 주어진 조건으로 결정해야 함",
