    "explanation": "**[핵심 개념]**\n부분적분(Integration by Parts)은 $\\int u \\, dv = uv - \\int v \\, du$ 공식으로, 곱의 형태인 함수를 적분할 때 사용한다. 이 문제에서는 다항식과 지수함수의 곱이므로 부분적분을 적용한다. 또한 $\\frac{d}{dx}[e^x] = e^x$이고 $\\int e^x dx = e^x + C$임을 활용한다.\n\n**[풀이]**\n\n$\\int xe^x dx$를 구하기 위해 부분적분을 사용한다.\n\n$u = x$, $dv = e^x dx$로 설정하면:\n- $du = dx$\n- $v = \\int e^x dx = e^x$\n\n부분적분 공식 $\\int u \\, dv = uv - \\int v \\, du$를 적용하면:\n\n$$\\int xe^x dx = x \\cdot e^x - \\int e^x dx$$\n\n$$= xe^x - e^x + C$$\n\n$$= e^x(x - 1) + C$$\n\n$$= (x-1)e^x + C$$\n\n**[정답 확인]**\n$(x-1)e^x + C$를 $x$에 대해 미분하면 $e^x + (x-1)e^x = xe^x = f(x)$가 되므로 정답이다.\n\n**[오답 분석]**\n- ① $xe^x + C$: 미분하면 $e^x + xe^x \\neq xe^x$ (오류)\n- ③ $(x+1)e^x + C$: 미분하면 $e^x + (x+1)e^x = (x+2)e^x \\neq xe^x$ (오류)\n- ④ $x^2e^x + C$: 미분하면 $2xe^x + x^2e^x \\neq xe^x$ (오류)\n- ⑤ $\\frac{x^2}{2}e^x + C$: 미분하면 $xe^x + \\frac{x^2}{2}e^x \\neq xe^x$ (오류)\n\n**[핵심 포인트]**\n다항식과 지수함수의 곱을 적분할 때는 **부분적분**을 사용하며, 다항식을 $u$로, 지수함수를 $dv$로 설정하는 것이 표준이다. 검증을 위해 미분으로 확인하는 습관이 중요하다.",
