    "explanation": "**[핵심 개념]**\n- 부정적분: $F'(x) = f(x)$를 만족하는 $F(x)$는 $f(x)$의 부정적분\n- 정적분과 부정적분의 관계: $G(x) = \\int_0^x f(t)dt$에서 $G'(x) = f(x)$이고 $G(0) = 0$\n- 부분적분: $\\int u \\, dv = uv - \\int v \\, du$ (다항식과 지수함수의 곱)\n- 초기조건을 이용한 적분상수 결정\n\n**[풀이]**\n\n**Step 1: $F(x)$ 구하기 (부분적분)**\n\n$F'(x) = f(x) = (x^2 + 1)e^x$이므로, $\\int (x^2 + 1)e^x dx$를 계산한다.\n\n부분적분을 두 번 적용한다:\n- $u = x^2 + 1$, $dv = e^x dx$\n- $du = 2x dx$, $v = e^x$\n\n$$\\int (x^2 + 1)e^x dx = (x^2 + 1)e^x - \\int 2xe^x dx$$\n\n두 번째 적분에 다시 부분적분:\n- $u = 2x$, $dv = e^x dx$\n- $du = 2 dx$, $v = e^x$\n\n$$\\int 2xe^x dx = 2xe^x - \\int 2e^x dx = 2xe^x - 2e^x$$\n\n따라서:\n$$\\int (x^2 + 1)e^x dx = (x^2 + 1)e^x - (2xe^x - 2e^x) + C$$\n$$= (x^2 + 1)e^x - 2xe^x + 2e^x + C$$\n$$= (x^2 - 2x + 3)e^x + C$$\n\n$F(0) = 1$이므로:\n$$F(0) = (0 - 0 + 3)e^0 + C = 3 + C = 1$$\n$$C = -2$$\n\n따라서 $F(x) = (x^2 - 2x + 3)e^x - 2$\n\n**Step 2: $G(x)$ 구하기**\n\n$$G(x) = \\int_0^x f(t)dt = \\int_0^x (t^2 + 1)e^t dt$$\n\n미적분학의 기본정리에 의해, $F(x) - F(0)$도 $\\int_0^x f(t)dt$와 같으므로:\n$$G(x) = F(x) - F(0) = (x^2 - 2x + 3)e^x - 2 - 1$$\n$$G(x) = (x^2 - 2x + 3)e^x - 3$$\n\n확인: $G(0) = 3e^0 - 3 = 0$ ✓\n\n**Step 3: $F(x) - G(x)$ 계산**\n\n$$F(x) - G(x) = [(x^2 - 2x + 3)e^x - 2] - [(x^2 - 2x + 3)e^x - 3]$$\n$$= (x^2 - 2x + 3)e^x - 2 - (x^2 - 2x + 3)e^x + 3$$\n$$= 1$$\n\n따라서 $ax^2 + bx + c = 1$이므로:\n$$a = 0, \\quad b = 0, \\quad c = 1$$\n\n**Step 4: 답 구하기**\n\n$$a + b + c = 0 + 0 + 1 = 1$$\n\n**[정답 확인]**\n$F(x) - G(x) = 1$은 상수함수이고, 이를 $ax^2 + bx + c$ 형태로 나타내면 $a=0, b=0, c=1$이므로 $a+b+c=1$이다.\n\n**[오답 분석]**\n- ① $-1$: 부호를 잘못 계산한 경우\n- ② $0$: $F(x) - G(x)$가 0이라고 잘못 생각한 경우\n- ④ $2$: 적분상수 계산 실수\n- ⑤ $3$: $F(0)$의 값을 다시 더한 경우\n\n**[핵심 포인트]**\n$F(x) - G(x)$는 $G(x) = \\int_0^x f(t)dt = F(x) - F(0)$의 성질을 이용하면, 결국 $F(0)$만 남는 상수함수가 된다. 초기조건이 주어진 부정적분 문제에서는 적분상수를 반드시 초기조건으로 결정해야 한다.",
