    "explanation": "**[핵심 개념]**\n정적분을 계산하기 위해서는 먼저 피적분함수의 부정적분(원시함수)을 구한 후, 미적분학의 기본정리를 이용하여 계산한다. 미적분학의 기본정리는 $\\int_{a}^{b} f(x)dx = [F(x)]_{a}^{b} = F(b) - F(a)$이다. 여기서 $F(x)$는 $f(x)$의 부정적분이다. 또한 적분 구간이 대칭일 때 피적분함수의 성질을 이용하면 계산을 간단히 할 수 있다.\n\n**[풀이]**\n\n주어진 적분을 계산한다:\n$$\\int_{-2}^{2} (x^3 + 2x^2) dx$$\n\n**Step 1: 피적분함수를 홀함수와 짝함수로 분해**\n\n$x^3$는 홀함수이다: $f(-x) = (-x)^3 = -x^3 = -f(x)$\n\n$2x^2$는 짝함수이다: $g(-x) = 2(-x)^2 = 2x^2 = g(x)$\n\n**Step 2: 홀함수의 성질 이용**\n\n대칭 구간 $[-a, a]$에서 홀함수의 적분은 0이다:\n$$\\int_{-2}^{2} x^3 dx = 0$$\n\n**Step 3: 짝함수 적분 계산**\n\n$$\\int_{-2}^{2} 2x^2 dx = 2\\int_{-2}^{2} x^2 dx = 2 \\cdot 2\\int_{0}^{2} x^2 dx = 4\\int_{0}^{2} x^2 dx$$\n\n$x^2$의 부정적분은 $\\frac{x^3}{3}$이므로:\n$$4\\int_{0}^{2} x^2 dx = 4\\left[\\frac{x^3}{3}\\right]_{0}^{2} = 4\\left(\\frac{8}{3} - 0\\right) = \\frac{32}{3}$$\n\n**Step 4: 최종 답**\n\n$$\\int_{-2}^{2} (x^3 + 2x^2) dx = 0 + \\frac{32}{3} = \\frac{32}{3}$$\n\n**[정답 확인]**\n홀함수 $x^3$는 대칭 구간에서 적분값이 0이 되고, 짝함수 $2x^2$만 계산하면 $\\frac{32}{3}$이 되어 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{16}{3}$: 짝함수 부분을 절반만 계산한 경우\n- ③ $8$: 홀함수 부분을 잘못 계산하거나 대칭성을 무시한 경우\n- ④ $\\frac{64}{3}$: 홀함수까지 포함하여 절댓값으로 계산한 경우\n- ⑤ $16$: 적분 계산 실수가 발생한 경우\n\n**[핵심 포인트]**\n1. 대칭 구간 $[-a, a]$에서는 홀함수의 적분은 0, 짝함수의 적분은 $2\\int_{0}^{a} f(x)dx$임을 활용하면 계산이 간단해진다.\n2. 피적분함수를 홀짝성으로 분석하여 적분을 단순화하는 것이 효율적이다.",
