    "explanation": "**[핵심 개념]**\n1. **함수의 기함수/우함수 성질**: 기함수 $g(x) = -g(-x)$는 대칭 구간에서 적분값이 0\n2. **함수 분해**: $f(x) = x^2 + 2x$를 우함수 $x^2$와 기함수 $2x$로 분리\n3. **정적분의 선형성**: $\\int_{-a}^{a} [f(x) + g(x)] dx = \\int_{-a}^{a} f(x) dx + \\int_{-a}^{a} g(x) dx$\n\n**[풀이]**\n\n**Step 1: 함수를 우함수와 기함수로 분해**\n\n$f(x) = x^2 + 2x$에서\n- $x^2$는 우함수 (짝함수): $(-x)^2 = x^2$\n- $2x$는 기함수 (홀함수): $2(-x) = -2x$ ✓ (문제에서 주어진 조건)\n\n**Step 2: 적분을 분리**\n\n$$\\int_{-2}^{2} f(x) dx = \\int_{-2}^{2} (x^2 + 2x) dx = \\int_{-2}^{2} x^2 dx + \\int_{-2}^{2} 2x dx$$\n\n**Step 3: 기함수의 적분 = 0**\n\n$g(x) = 2x$는 기함수이고, 대칭 구간 $[-2, 2]$에서의 적분이므로:\n$$\\int_{-2}^{2} 2x dx = 0$$\n\n(기함수는 대칭 구간에서 음의 넓이와 양의 넓이가 상쇄됨)\n\n**Step 4: 우함수의 적분만 계산**\n\n$$\\int_{-2}^{2} x^2 dx = \\left[\\frac{x^3}{3}\\right]_{-2}^{2} = \\frac{2^3}{3} - \\frac{(-2)^3}{3}$$\n\n$$= \\frac{8}{3} - \\frac{-8}{3} = \\frac{8}{3} + \\frac{8}{3} = \\frac{16}{3}$$\n\n**Step 5: 최종 답**\n\n$$\\int_{-2}^{2} f(x) dx = \\frac{16}{3} + 0 = \\frac{16}{3}$$\n\n**[정답 확인]**\n기함수 $2x$의 대칭 구간 적분이 0이므로, $x^2$ 항만 계산하면 $\\frac{16}{3}$이 정답이다.\n\n**[오답 분석]**\n- ① $\\frac{8}{3}$: $x^2$의 적분을 한쪽 구간 $[0,2]$만 계산한 경우\n- ③ $\\frac{20}{3}$: 계산 실수로 $2x$ 항을 포함하거나 중간값을 잘못 계산\n- ④ $\\frac{28}{3}$: $\\int_{-2}^{2} |x^2 + 2x| dx$로 잘못 해석\n- ⑤ $\\frac{32}{3}$: $[0,2]$ 구간에서만 적분을 2배한 경우\n\n**[핵심 포인트]**\n1. **대칭 구간에서 기함수의 적분은 항상 0**: 이를 이용하면 복잡한 계산을 단순화할 수 있다.\n2. **함수 분해의 중요성**: 주어진 함수를 우함수와 기함수로 분해하면 계산이 매우 효율적이다.",
