    "explanation": "**[핵심 개념]**\n- 정적분의 정의: $\\displaystyle\\int_{a}^{b} f(x) \\, dx$는 구간 $[a,b]$에서 함수 $f(x)$의 넓이를 의미\n- 부정적분 공식: $\\displaystyle\\int x^n \\, dx = \\frac{x^{n+1}}{n+1} + C$ (단, $n \\neq -1$)\n- 정적분 계산: $\\displaystyle\\int_{a}^{b} f(x) \\, dx = [F(x)]_{a}^{b} = F(b) - F(a)$ (여기서 $F$는 $f$의 부정적분)\n- 짝함수의 성질: $f(-x) = f(x)$일 때, $\\displaystyle\\int_{-a}^{a} f(x) \\, dx = 2\\int_{0}^{a} f(x) \\, dx$\n\n**[풀이]**\n\n**Step 1: 함수의 성질 확인**\n\n$f(x) = x^2 + 2$에서 $f(-x) = (-x)^2 + 2 = x^2 + 2 = f(x)$\n\n따라서 $f(x)$는 짝함수이다.\n\n**Step 2: 부정적분 구하기**\n\n$$F(x) = \\int (x^2 + 2) \\, dx = \\frac{x^3}{3} + 2x + C$$\n\n**Step 3: 조건 (가) 계산**\n\n$$\\int_{-2}^{2} f(x) \\, dx = \\left[\\frac{x^3}{3} + 2x\\right]_{-2}^{2}$$\n\n$$= \\left(\\frac{8}{3} + 4\\right) - \\left(\\frac{-8}{3} - 4\\right)$$\n\n$$= \\frac{8}{3} + 4 + \\frac{8}{3} + 4$$\n\n$$= \\frac{16}{3} + 8 = \\frac{16 + 24}{3} = \\frac{40}{3}$$\n\n**Step 4: 조건 (나) 계산**\n\n$$\\int_{0}^{2} f(x) \\, dx = \\left[\\frac{x^3}{3} + 2x\\right]_{0}^{2}$$\n\n$$= \\left(\\frac{8}{3} + 4\\right) - 0$$\n\n$$= \\frac{8}{3} + 4 = \\frac{8 + 12}{3} = \\frac{20}{3}$$\n\n**Step 5: 조건 (가)를 조건 (나)로 나누기**\n\n$$\\frac{\\text{(가)}}{\\text{(나)}} = \\frac{\\dfrac{40}{3}}{\\dfrac{20}{3}} = \\frac{40}{3} \\times \\frac{3}{20} = \\frac{40}{20} = 2$$\n\n**[정답 확인]**\n\n짝함수의 성질에 의해 $\\int_{-2}^{2} f(x) \\, dx = 2\\int_{0}^{2} f(x) \\, dx$이므로, 조건 (가)를 조건 (나)로 나누면 항상 2가 되어 정답 ③이 맞다.\n\n**[오답 분석]**\n\n- ① $1$: 조건 (가)와 (나)가 같다고 잘못 생각한 경우\n- ② $\\dfrac{3}{2}$: 계산 실수로 부정적분이나 정적분 계산을 잘못한 경우\n- ④ $\\dfrac{5}{2}$: 짝함수 성질을 무시하고 잘못 계산한 경우\n- ⑤ $3$: 적분값 계산에서 실수한 경우\n\n**[핵심 포인트]**\n\n1. 짝함수 $f(x)$에 대해 $\\displaystyle\\int_{-a}^{a} f(x) \\, dx = 2\\int_{0}^{a} f(x) \\, dx$는 매우 중요한 성질이다.\n2. 이 문제에서는 짝함수 성질을 이용하면 계산 과정을 크게 단축할 수 있다.",
