    "explanation": "**[핵심 개념]**\n\n임의의 함수 $f(x)$는 우함수(짝함수)와 기함수(홀함수)의 합으로 유일하게 표현될 수 있다.\n- 우함수 $g(x)$: $g(-x) = g(x)$이고, $\\int_{-a}^{a} g(x)dx = 2\\int_{0}^{a} g(x)dx$\n- 기함수 $h(x)$: $h(-x) = -h(x)$이고, $\\int_{-a}^{a} h(x)dx = 0$\n\n일반적으로 $f(x) = g(x) + h(x)$로 나타낼 때:\n$$g(x) = \\frac{f(x) + f(-x)}{2}, \\quad h(x) = \\frac{f(x) - f(-x)}{2}$$\n\n**[풀이]**\n\n**Step 1: 우함수와 기함수 분리**\n\n주어진 함수 $f(x) = x^2 + 2x$에 대해 $f(-x)$를 구한다.\n$$f(-x) = (-x)^2 + 2(-x) = x^2 - 2x$$\n\n**Step 2: 우함수 구하기**\n\n$$g(x) = \\frac{f(x) + f(-x)}{2} = \\frac{(x^2 + 2x) + (x^2 - 2x)}{2} = \\frac{2x^2}{2} = x^2$$\n\n**Step 3: 기함수 구하기**\n\n$$h(x) = \\frac{f(x) - f(-x)}{2} = \\frac{(x^2 + 2x) - (x^2 - 2x)}{2} = \\frac{4x}{2} = 2x$$\n\n검증: $g(x) + h(x) = x^2 + 2x = f(x)$ ✓\n\n**Step 4: 정적분 계산**\n\n$$\\int_{-2}^{2} f(x)dx = \\int_{-2}^{2} [g(x) + h(x)]dx = \\int_{-2}^{2} g(x)dx + \\int_{-2}^{2} h(x)dx$$\n\n우함수의 성질을 이용:\n$$\\int_{-2}^{2} g(x)dx = \\int_{-2}^{2} x^2 dx = 2\\int_{0}^{2} x^2 dx = 2\\left[\\frac{x^3}{3}\\right]_{0}^{2} = 2 \\cdot \\frac{8}{3} = \\frac{16}{3}$$\n\n기함수의 성질을 이용:\n$$\\int_{-2}^{2} h(x)dx = \\int_{-2}^{2} 2x dx = 0$$\n\n**Step 5: 최종 답**\n\n$$\\int_{-2}^{2} f(x)dx = \\frac{16}{3} + 0 = \\frac{16}{3}$$\n\n**[정답 확인]**\n\n우함수와 기함수로 분리하면 기함수의 적분은 0이 되므로, 우함수 $x^2$만 적분하면 $\\frac{16}{3}$을 얻는다.\n\n**[오답 분석]**\n\n- ① $\\frac{8}{3}$: $\\int_{0}^{2} x^2 dx = \\frac{8}{3}$이므로, 대칭성을 무시하고 반만 계산한 경우\n- ③ $\\frac{20}{3}$: 우함수 부분을 잘못 계산하거나 $2x$ 항을 잘못 처리한 경우\n- ④ $\\frac{24}{3} = 8$: 기함수 부분을 잘못 적분하여 더한 경우\n- ⑤ $\\frac{28}{3}$: 계산 실수로 인한 오답\n\n**[핵심 포인트]**\n\n1. 대칭 구간 $[-a, a]$에서 기함수의 정적분은 항상 0이므로, 함수를 분리하면 계산이 단순화된다.\n2. 우함수와 기함수의 분해: $g(x) = \\frac{f(x)+f(-x)}{2}$, $h(x) = \\frac{f(x)-f(-x)}{2}$를 기억한다.",
