    "explanation": "**[핵심 개념]**\n곡선으로 둘러싸인 도형의 넓이는 정적분으로 구한다. 곡선 $y=f(x)$, $x$축, 그리고 $x=a$, $x=b$로 둘러싸인 도형의 넓이는 $\\int_a^b f(x)dx$이다. 또한 곡선이 $x$축 위에 있으므로 $y \\geq 0$인 영역의 넓이를 구하는 상황이다.\n\n**[풀이]**\n\n곡선 $y=3x^2$은 $x$축과 원점에서 만나고, $x \\geq 0$에서 항상 $y \\geq 0$이다.\n\n문제에서 요구하는 도형은:\n- 곡선: $y = 3x^2$\n- $x$축: $y = 0$\n- 수직선: $x = 2$\n- 원점: $x = 0$ (시작점)\n\n이 네 경계로 둘러싸인 도형이다.\n\n넓이를 구하기 위해 정적분을 계산한다:\n\n$$\\text{넓이} = \\int_0^2 3x^2 \\, dx$$\n\n적분을 계산하면:\n\n$$\\int_0^2 3x^2 \\, dx = \\left[3 \\cdot \\frac{x^3}{3}\\right]_0^2 = \\left[x^3\\right]_0^2$$\n\n$$= 2^3 - 0^3 = 8 - 0 = 8$$\n\n문제를 재해석하면, \"$x$축과 $x=2$로 둘러싸인 도형\"이 원점이 아닌 다른 지점을 포함할 수 있다. 만약 곡선이 $x$축과 만나는 다른 점이 있다면. 하지만 $y=3x^2$은 $x=0$에서만 $x$축과 만난다.\n\n정답이 12이려면:\n$$\\int_0^2 3x^2 \\, dx = 8 \\text{ (계산 재확인)}$$\n\n혹은 문제가 다른 함수일 수 있으나, 주어진 조건으로는 8이 맞다. 정답 키가 ④번이 12라면, 다른 곡선(예: $y=6x^2$ 또는 $y=3x$)이거나 적분 구간이 다를 수 있다.\n\n$y=3x^2$에서 $\\int_0^2 3x^2dx = 8$이 맞으므로, 정답 가 필요하다.\n\n**[정답 확인]**\n$\\int_0^2 3x^2 \\, dx = [x^3]_0^2 = 8$ 따라서 넓이는 8이다. (정답 키가 12라면 문제 조건 재확인 필요)\n\n**[오답 분석]**\n- ① 6: $\\int_0^2 3x^2dx$를 잘못 계산하여 $3 \\times 2 = 6$으로 오류\n- ③ 10: 실수하여 $8+2$ 정도로 산정\n- ⑤ 14: 적분값에 추가 값을 더한 오류\n\n**[핵심 포인트]**\n정적분으로 넓이를 구할 때는 피적분함수를 정확히 파악하고, 적분 구간의 시작점과 끝점을 명확히 해야 한다. $\\int x^n dx = \\frac{x^{n+1}}{n+1} + C$ 공식을 정확히 적용한다.",
