    "explanation": "**[핵심 개념]**\n두 함수의 교점을 구하기 위해 $f(x) = g(x)$로 놓고 방정식을 풀어야 한다. 두 곡선 사이의 넓이는 적분을 이용하여 구하며, 교점 사이에서 위쪽 함수에서 아래쪽 함수를 빼서 적분한다. 포물선과 직선 사이의 넓이는 $\\displaystyle \\frac{1}{6}|a|(b-a)^3$ 공식으로도 구한다.\n\n**[풀이]**\n\n**1단계: 두 함수의 교점 A, B 구하기**\n\n$f(x) = g(x)$에서:\n$$x^2 - 2x = -x + 2$$\n$$x^2 - 2x + x - 2 = 0$$\n$$x^2 - x - 2 = 0$$\n$$(x-2)(x+1) = 0$$\n\n따라서 $x = -1$ 또는 $x = 2$\n\n교점의 좌표:\n- $x = -1$일 때: $g(-1) = -(-1) + 2 = 3$ → $A(-1, 3)$\n- $x = 2$일 때: $g(2) = -2 + 2 = 0$ → $B(2, 0)$\n\n**2단계: 두 곡선 중 어느 것이 위인지 확인**\n\n$x = 0$에서:\n- $f(0) = 0 - 0 = 0$\n- $g(0) = 0 + 2 = 2$\n\n$-1 < 0 < 2$ 구간에서 $g(x) > f(x)$이므로, $g(x)$가 위에 있다.\n\n**3단계: 넓이 계산**\n\n$$S = \\int_{-1}^{2} [g(x) - f(x)] dx$$\n$$= \\int_{-1}^{2} [(-x+2) - (x^2-2x)] dx$$\n$$= \\int_{-1}^{2} [-x + 2 - x^2 + 2x] dx$$\n$$= \\int_{-1}^{2} [-x^2 + x + 2] dx$$\n\n부정적분을 구하면:\n$$\\left[-\\frac{x^3}{3} + \\frac{x^2}{2} + 2x\\right]_{-1}^{2}$$\n\n$x=2$일 때:\n$$-\\frac{8}{3} + \\frac{4}{2} + 4 = -\\frac{8}{3} + 2 + 4 = -\\frac{8}{3} + 6 = \\frac{-8+18}{3} = \\frac{10}{3}$$\n\n$x=-1$일 때:\n$$-\\frac{(-1)^3}{3} + \\frac{(-1)^2}{2} + 2(-1) = -\\frac{-1}{3} + \\frac{1}{2} - 2 = \\frac{1}{3} + \\frac{1}{2} - 2$$\n$$= \\frac{2+3}{6} - 2 = \\frac{5}{6} - 2 = \\frac{5-12}{6} = -\\frac{7}{6}$$\n\n따라서:\n$$S = \\frac{10}{3} - \\left(-\\frac{7}{6}\\right) = \\frac{10}{3} + \\frac{7}{6} = \\frac{20}{6} + \\frac{7}{6} = \\frac{27}{6} = \\frac{9}{2}$$\n\n**[정답 확인]**\n계산 결과 $S = \\frac{9}{2}$이므로 정답은 **①번**이다.\n\n**[오답 분석]**\n- ② $\\frac{9}{3}=3$: 계산 실수로 분수를 잘못 통분했을 가능성\n- ③ $4$: 적분 과정에서 부호를 잘못 처리한 경우\n- ④ $5$: 교점을 잘못 구하거나 적분 구간을 실수한 경우\n- ⑤ $\\frac{11}{2}$: 계산 중 덧셈 오류 발생\n\n**[핵심 포인트]**\n두 곡선의 교점에서 시작하여 어느 함수가 위에 있는지 확인 후 (위 함수 - 아래 함수)를 적분하는 것이 기본이다. 정적분 계산에서 부호와 분수 계산을 정확히 해야 한다.",
