    "explanation": "**[핵심 개념]**\n물리학에서 변위(displacement)는 속도를 시간에 대해 적분한 값이다. 속도 함수 $v(t)$가 주어질 때, $t=a$에서 $t=b$까지의 변위는 다음과 같이 구한다:\n\n$$\\text{변위} = \\int_a^b v(t) \\, dt$$\n\n이는 미적분학의 기본정리를 물리에 응용한 것으로, 속도의 시간에 따른 누적값이 변위가 됨을 의미한다.\n\n**[풀이]**\n\n**1단계: 변위 공식 설정**\n\n$t=0$에서 $t=2$초까지의 변위는:\n$$s = \\int_0^2 v(t) \\, dt = \\int_0^2 (3t + 2) \\, dt$$\n\n**2단계: 부정적분 계산**\n\n$3t + 2$를 $t$에 대해 적분한다:\n$$\\int (3t + 2) \\, dt = 3 \\cdot \\frac{t^2}{2} + 2t + C = \\frac{3t^2}{2} + 2t + C$$\n\n**3단계: 정적분 계산 (미적분학의 기본정리 적용)**\n\n$$s = \\left[\\frac{3t^2}{2} + 2t\\right]_0^2$$\n\n상한 $t=2$를 대입:\n$$\\frac{3(2)^2}{2} + 2(2) = \\frac{3 \\cdot 4}{2} + 4 = \\frac{12}{2} + 4 = 6 + 4 = 10$$\n\n하한 $t=0$을 대입:\n$$\\frac{3(0)^2}{2} + 2(0) = 0$$\n\n따라서:\n$$s = 10 - 0 = 10 \\text{ (m)}$$\n\n**[정답 확인]**\n속도함수를 0에서 2까지 적분하면 10 m이 되므로 정답은 ④이다.\n\n**[오답 분석]**\n\n- **① 4 m**: $v(t)$의 초기값만 고려하거나 잘못된 계산\n- **② 6 m**: 상한값만 계산하여 $\\frac{3t^2}{2}$ 부분만 구한 경우\n- **③ 8 m**: 적분 과정에서 계수를 잘못 처리한 경우\n- **⑤ 12 m**: 적분 상한을 $t=2$가 아닌 다른 값으로 잘못 설정\n\n**[핵심 포인트]**\n- **속도의 적분 = 변위**: $v(t) \\, dt$를 적분하면 변위를 구한다.\n- **정적분의 계산**: 부정적분을 먼저 구한 후 상한과 하한을 대입하여 차를 구하는 것이 핵심이다.",
