    "answer": 3,
    "explanation": "**[핵심 개념]**\n\n이동거리는 속도의 절댓값을 시간에 대해 적분한 것이다. 속도 $v(t)$가 음수인 구간과 양수인 구간을 나누어 계산해야 한다. 단순 변위(displacement)는 $\\int v(t)dt$이지만, 이동거리(distance)는 $\\int |v(t)|dt$이다.\n\n**[풀이]**\n\n**Step 1: 속도함수의 부호 결정**\n\n$v(t) = t^2 - 4t + 3$을 인수분해하면:\n$$v(t) = (t-1)(t-3)$$\n\n$0 \\leq t \\leq 3$ 구간에서 $v(t)$의 부호를 조사한다:\n- $0 \\leq t < 1$: $v(t) > 0$ (양수)\n- $1 < t < 3$: $v(t) < 0$ (음수)\n- $t = 1, 3$: $v(t) = 0$\n\n**Step 2: 이동거리 계산**\n\n이동거리는 다음과 같이 나누어 적분한다:\n$$\\text{이동거리} = \\int_0^1 v(t)dt + \\int_1^3 |v(t)|dt = \\int_0^1 v(t)dt - \\int_1^3 v(t)dt$$\n\n**Step 3: 부정적분 계산**\n\n$$\\int v(t)dt = \\int (t^2 - 4t + 3)dt = \\frac{t^3}{3} - 2t^2 + 3t + C$$\n\n**Step 4: 첫 번째 구간 ($0 \\leq t \\leq 1$)**\n\n$$\\int_0^1 v(t)dt = \\left[\\frac{t^3}{3} - 2t^2 + 3t\\right]_0^1 = \\frac{1}{3} - 2 + 3 = \\frac{4}{3}$$\n\n**Step 5: 두 번째 구간 ($1 \\leq t \\leq 3$)**\n\n$$\\int_1^3 v(t)dt = \\left[\\frac{t^3}{3} - 2t^2 + 3t\\right]_1^3$$\n\n$t=3$일 때: $\\frac{27}{3} - 2(9) + 3(3) = 9 - 18 + 9 = 0$\n\n$t=1$일 때: $\\frac{1}{3} - 2 + 3 = \\frac{4}{3}$\n\n$$\\int_1^3 v(t)dt = 0 - \\frac{4}{3} = -\\frac{4}{3}$$\n\n**Step 6: 최종 계산**\n\n$$\\text{이동거리} = \\int_0^1 v(t)dt - \\int_1^3 v(t)dt = \\frac{4}{3} - \\left(-\\frac{4}{3}\\right) = \\frac{4}{3} + \\frac{4}{3} = \\frac{8}{3}$$\n\n**[정답 확인]**\n\n속도가 $t=1$에서 양수에서 음수로 변하므로, 물체는 $t=1$까지 한 방향으로 움직였다가 반대 방향으로 돌아온다. 각 구간의 이동거리를 모두 더하면 $\\frac{4}{3} + \\frac{4}{3} = \\frac{8}{3}$ m이다.\n\n**[오답 분석]**\n\n- **① 2 m**: 절댓값을 고려하지 않고 단순 적분한 경우\n- **② 4 m**: 계산 실수로 중간 값을 잘못 구한 경우\n- **③ $\\frac{4}{3}$ m**: $0$부터 $1$까지의 이동거리만 구한 경우\n- **⑤ 6 m**: 절댓값 처리 과정에서 구간을 잘못 나누거나 중복 계산한 경우\n\n**[핵심 포인트]**\n\n이동거리 문제에서는 반드시 $|v(t)|$를 적분해야 한다. 속도가 0이 되는 지점을 찾아 구간을 나누고, 각 구간에서 속도의 부호를 확인한 후 절댓값을 취해서 더해야 한다.",
