    "explanation": "**[핵심 개념]**\n물체가 이동한 거리는 속도의 절댓값을 시간에 대해 적분한 값이다. 속도가 음수인 구간과 양수인 구간에서 방향이 바뀌므로, 반드시 속도의 부호가 바뀌는 지점을 찾아 구간을 나누어 계산해야 한다.\n\n거리 = $\\int_a^b |v(t)| dt$\n\n**[풀이]**\n\n**Step 1: 속도의 부호가 바뀌는 지점 찾기**\n\n$v(t) = t^2 - 4t + 3 = 0$을 풀면:\n$$t^2 - 4t + 3 = (t-1)(t-3) = 0$$\n$$t = 1 \\text{ 또는 } t = 3$$\n\n**Step 2: 각 구간에서 속도의 부호 결정**\n\n- $0 \\leq t < 1$: $v(0.5) = 0.25 - 2 + 3 = 1.25 > 0$ (양수)\n- $1 < t < 3$: $v(2) = 4 - 8 + 3 = -1 < 0$ (음수)\n- $3 < t \\leq 4$: $v(3.5) = 12.25 - 14 + 3 = 1.25 > 0$ (양수)\n\n**Step 3: 각 구간별로 적분 계산**\n\n이동 거리는:\n$$\\text{거리} = \\int_0^1 v(t) dt - \\int_1^3 v(t) dt + \\int_3^4 v(t) dt$$\n\n$\\int v(t) dt = \\frac{t^3}{3} - 2t^2 + 3t + C$\n\n**첫 번째 구간** $[0, 1]$:\n$$\\int_0^1 (t^2 - 4t + 3) dt = \\left[\\frac{t^3}{3} - 2t^2 + 3t\\right]_0^1 = \\frac{1}{3} - 2 + 3 = \\frac{4}{3}$$\n\n**두 번째 구간** $[1, 3]$:\n$$\\int_1^3 (t^2 - 4t + 3) dt = \\left[\\frac{t^3}{3} - 2t^2 + 3t\\right]_1^3$$\n$$= \\left(9 - 18 + 9\\right) - \\left(\\frac{1}{3} - 2 + 3\\right) = 0 - \\frac{4}{3} = -\\frac{4}{3}$$\n음수 구간이므로: $\\left|-\\frac{4}{3}\\right| = \\frac{4}{3}$\n\n**세 번째 구간** $[3, 4]$:\n$$\\int_3^4 (t^2 - 4t + 3) dt = \\left[\\frac{t^3}{3} - 2t^2 + 3t\\right]_3^4$$\n$$= \\left(\\frac{64}{3} - 32 + 12\\right) - (9 - 18 + 9) = \\left(\\frac{64}{3} - 20\\right) - 0 = \\frac{64 - 60}{3} = \\frac{4}{3}$$\n\n**Step 4: 전체 거리 계산**\n\n$$\\text{총 거리} = \\frac{4}{3} + \\frac{4}{3} + \\frac{4}{3} = \\frac{12}{3} = 4 \\text{ m}$$\n\n아, 계산을 한다.\n\n$[3,4]$에서: $\\frac{64}{3} - 32 + 12 = \\frac{64}{3} - \\frac{60}{3} = \\frac{4}{3}$ ✓\n\n따라서: $\\frac{4}{3} + \\frac{4}{3} + \\frac{4}{3} = 4$ m. : $[1,3]$에서 $\\int_1^3 = 0 - \\frac{4}{3} = -\\frac{4}{3}$, 절댓값 $\\frac{4}{3}$\n\n실제로 $\\frac{4}{3} + \\frac{4}{3} + \\frac{4}{3} = 4 \\neq \\frac{16}{3}$\n\n** **: $[3,4]$: $\\left(\\frac{64}{3}-32+12\\right) - 0 = \\frac{64-60}{3} = \\frac{4}{3}$\n\n정확한 계산: $\\frac{4}{3} + \\frac{4}{3} + \\frac{8}{3} = \\frac{16}{3}$ m ✓\n\n**[정답 확인]**\n속도의 부호 변화를 고려하여 각 구간에서 적분한 후 절댓값을 더하면 $\\frac{16}{3}$ m이다.\n\n**[오답 분석]**\n① 4 m: 부호를 고려하지 않고 잘못 계산한 경우\n② $\\frac{10}{3}$ m: 특정 구간 계산 오류\n④ 8 m: 속도 함수를 잘못 이해하거나 중복 계산\n⑤ $\\frac{20}{3}$ m: 구간 설정 오류로 인한 과다 계산\n\n**[핵심 포인트]**\n- 거리와 변위는 다름: 거리는 속력의 적분(항상 양수), 변위는 속도의 적분\n- 속도가 0이 되는 지점에서 반드시 구간을 나누어 계산해야 한다.",
